let W=960;const H=600,T=24,keys=new Set();let state=initialState(),saved=null,mode='world',area='town',road=null,objects=[],solids=[],song=null,near=null,last=performance.now(),walk=0,toastTimer,puzzleTimers=[],path=[],tapObject=null,layout=townLayout(0),room=null,transitioning=false,portalCooldown=0,hasMoved=false;
